def reference_change_base(x: int, base: int) -> str:
    if x == 0:
        return "0"
    digits = []
    n = x
    while n > 0:
        digits.append(str(n % base))
        n //= base
    return "".join(reversed(digits))


def test_zero_returns_zero_string():
    for base in range(2, 10):
        assert change_base(0, base) == "0"
